import{_ as i,o as a,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Research 0003 — WKWebView offline behavior and service-worker constraints","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/research/0003-webview-offline-behavior.md"},"headers":[],"relativePath":"apps/mobile/research/0003-webview-offline-behavior.md","filePath":"apps/mobile/research/0003-webview-offline-behavior.md"}'),s={name:"apps/mobile/research/0003-webview-offline-behavior.md"};function t(n,e,l,h,c,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="research-0003-—-wkwebview-offline-behavior-and-service-worker-constraints" tabindex="-1">Research 0003 — WKWebView offline behavior and service-worker constraints <a class="header-anchor" href="#research-0003-—-wkwebview-offline-behavior-and-service-worker-constraints" aria-label="Permalink to &quot;Research 0003 — WKWebView offline behavior and service-worker constraints&quot;">​</a></h1><p><strong>Status:</strong> Pending spike. Tracked centrally as sovereign epic task 20.10 and shared with sovereign workstream 0001; run once, both workstreams consume the finding. This doc is the place that finding gets recorded from this repo&#39;s side once the spike lands.</p><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>Once <a href="./../adrs/0005-server-url-not-bundled-assets.html">ADR 0005</a> commits this shell to loading <code>server.url</code> over <code>https</code> (required for a service worker to exist at all), how much of Sovereign&#39;s PWA offline behavior actually survives inside a Capacitor WKWebView in practice? Assumption is not evidence here — this has to be measured against a real Capacitor build, not inferred from how service workers behave in Safari or Chrome directly.</p><h2 id="why-this-matters-here-specifically" tabindex="-1">Why this matters here specifically <a class="header-anchor" href="#why-this-matters-here-specifically" aria-label="Permalink to &quot;Why this matters here specifically&quot;">​</a></h2><ul><li>Determines whether offline is a <strong>feature of the first native release</strong> or a <strong>documented follow-up</strong> — a scope decision, not a go/no-go one. This leg always produces a usable answer either way.</li><li>iOS is known to evict <code>WKWebsiteDataStore</code> under storage pressure or prolonged non-use. For this whole-instance shell the visible effect of eviction is a forced re-login and a cold cache — annoying, not silent data loss, since the instance (not the shell) is the source of truth. Still needs to be measured, not assumed.</li><li>A negative result narrows this repo&#39;s Phase 1 scope; it does not block the release. See <a href="./../epics/shell.html">epics/shell.md</a> kill criteria.</li></ul><h2 id="what-the-spike-needs-to-answer" tabindex="-1">What the spike needs to answer <a class="header-anchor" href="#what-the-spike-needs-to-answer" aria-label="Permalink to &quot;What the spike needs to answer&quot;">​</a></h2><ol><li>Does a service worker registered by the loaded instance actually install and activate inside a Capacitor WKWebView pointed at <code>server.url</code>?</li><li>What survives a forced offline toggle mid-session — cached shell chrome, cached data, neither?</li><li>How does <code>WKWebsiteDataStore</code> eviction actually behave under realistic storage pressure and idle duration on a physical device (not a simulator)?</li><li>Does anything differ meaningfully between iOS and Android here, given Android&#39;s WebView has different service-worker and storage-eviction behavior?</li></ol><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Not yet decided — pending the spike. Do not build Phase 1 offline-dependent UX ahead of this finding; see <a href="./../epics/shell.html">epics/shell.md</a> leg 1 for sequencing.</p>',10)])])}const u=i(s,[["render",t]]);export{p as __pageData,u as default};
